"""rework Perseus latin-analyses.txt into Python dictionary"""
#!TODO
#add count to ambiguous words, like, pos_0, pos_1, pos_3 ...
#put word type w/in the pos, b/c/ some ambiguous forms could be of two types
import re
from pprint import pprint

with open('./latin-analyses.txt') as file_opened:
    string_raw = file_opened.read()
    string_rows = string_raw.splitlines()
    inflections = {}
    inflection = {}#perseus_pos = {}
    inflected = {}
    for row in string_rows:
        headword = row.split('\t', 1)[0]
        analyses_string = row.split('\t', 1)[1]
        reg_bracket = re.compile('\{.*?\}')
        analyses = reg_bracket.findall(analyses_string)
        for analysis in analyses:
            parts = analysis.split('\t')
            first = parts[0][1:]
            gloss = parts[1]
            third = parts[2][:-1]
            reg_digits = re.compile('\w+')
            perseus_headword_id = reg_digits.findall(first)[0]
            perseus_pos_id = reg_digits.findall(first)[1]
            perseus_parsed = reg_digits.findall(first)[2]
            try:
                perseus_headword = reg_digits.findall(first)[3]
            except:
                pass
            pos = third.split(' ')
            word_dict = {}
            pos_dict = {}
            #!come back to this, add pos counter for ambiguous forms
            #pos_counter = 0
            if pos[0] in ('fut', 'futperf', 'imperf', 'perf', 'pres', 'plup'):
                pos_dict['type'] = 'verb'
                pos_dict['tense'] = pos[0]
                if pos[1] in ('ind', 'imperat', 'subj'):
                    pos_dict['mood'] = pos[1]
                    if pos[2] in ('act', 'pass'):
                        pos_dict['voice'] = pos[2]
                        if pos[3] in ('1st', '2nd', '3rd'):
                            pos_dict['person'] = pos[3]
                            if pos[4] in ('pl', 'sg'):
                                pos_dict['number'] = pos[4]
                                word_dict['pos'] = pos_dict
                                inflections[headword] = word_dict
                            else:
                                pass
                        else:
                            pass
                    else:
                        pass
                elif pos[1] in ('part'):
                    pos_dict['tense'] = pos[0]
                    pos_dict['participle'] = pos[1]
                    if pos[2] in ('act', 'pass'):
                        pos_dict['voice'] = pos[2]
                        if pos[3] in ('fem', 'masc', 'neut'):
                            pos_dict['gender'] = pos[3]
                            if pos[4] in ('abl', 'acc', 'dat', 'gen', 'voc', 'nom', 'nom/voc', 'nom/voc/acc'):
                                pos_dict['case'] = pos[4]
                                try:
                                    if pos[5] in ('pl', 'sg'):
                                        pos_dict['number'] = pos[5]
                                        word_dict['pos'] = pos_dict
                                        inflections[headword] = word_dict
                                    else:
                                        pass
                                #~10 -iens participles w/o number
                                except:
                                    pos_dict['number'] = 'sg'
                                    word_dict['pos'] = pos_dict
                                    inflections[headword] = word_dict
                    #b/c voice left off present tense participles
                    elif pos[2] in ('masc/fem/neut', 'masc/fem', 'neut'):
                        pos_dict['voice'] = 'act'
                        if pos[3] in ('acc', 'gen', 'abl', 'dat', 'nom/voc/acc', 'nom/voc'):
                            if pos[3] in ('pl', 'sg'):
                                pos_dict['number'] = pos[4]
                                word_dict['pos'] = pos_dict
                                inflections[headword] = word_dict
                        else:
                            pass
                    else:
                        if pos[2] in ('abl', 'dat', 'gen'):
                            #b/c voice left off present voice participles
                            pos_dict['voice'] = 'act'
                            word_dict['pos'] = pos_dict
                            inflections[headword] = word_dict
                        else:
                            pass
                elif pos[1] in ('inf'):
                    if pos[2] in ('act', 'pass'):
                        pos_dict['voice'] = pos[2]
                        word_dict['pos'] = pos_dict
                        inflections[headword] = word_dict
                    else:
                        pass
                elif pos[1] in ('act', 'pass'):
                    #ferre verbs
                    pos_dict['voice'] = pos[1]
                    if pos[2] in ('1st', '2nd', '3rd'):
                        pos_dict['person'] = pos[2]
                        if pos[3] in ('pl', 'sg'):
                            pos_dict['number'] = pos[3]
                            word_dict['pos'] = pos_dict
                            inflections[headword] = word_dict
                        else:
                            pass
                    else:
                        pass
                else:
                    pass
            elif pos[0] == 'gerundive':
                pos_dict['type'] = 'gerundive'
                if pos[1] in ('fem', 'neut', 'masc', 'masc/neut'):
                    pos_dict['gender'] = pos[1]
                    if pos[2] in ('abl', 'acc', 'dat', 'gen', 'voc', 'nom', 'nom/voc', 'nom/voc/acc'):
                        if pos[3] in ('pl', 'sg'):
                            pos_dict['number'] = pos[3]
                            word_dict['pos'] = pos_dict
                            inflections[headword] = word_dict
                        else:
                            pass
                    else:
                        pass
                else:
                    pass
            elif pos[0] in ('fem', 'masc', 'neut', 'masc/fem/neut', 'masc/fem', 'masc/neut'):
                pos_dict['type'] = 'substantive'
                pos_dict['gender'] = pos[0]
                try:
                    if pos[1] in ('abl', 'acc', 'dat', 'gen', 'voc', 'nom', 'nom/voc', 'nom/voc/acc'):
                        pos_dict['case'] = pos[1]
                        if pos[2] in ('pl', 'sg'):
                            pos_dict['number'] = pos[2]
                        else:
                            if pos[2] in ('comp', 'superl'):
                                pos_dict['comparison'] = pos[2]
                                word_dict['pos'] = pos_dict
                                inflections[headword] = word_dict
                            else:
                                pass
                    else:
                        if pos[1] in ('pl', 'sg'):
                            pos_dict['number'] = pos[1]
                            word_dict['pos'] = pos_dict
                            inflections[headword] = word_dict
                except:
                    pos_dict['case'] = 'indeclinable'
                    pos_dict['gender'] = pos[0]
                    pos_dict['number'] = 'sg'
                    word_dict['pos'] = pos_dict
                    inflections[headword] = word_dict
            elif pos[0] == 'supine':
                pos_dict['type'] = pos[0]
                if pos[1] == 'neut':
                    pos_dict['gender'] = pos[1]
                    if pos[2] in ('nom', 'dat'):
                        pos_dict['case'] = pos[2]
                        if pos[3] == 'sg':
                            pos_dict['number'] = pos[3]
                            word_dict['pos'] = pos_dict
                            inflections[headword] = word_dict
                    else:
                        pass
                else:
                    pass
            elif pos[0] == 'indeclform':
                pos_dict['case'] = pos[0]
                pos_dict['type'] = pos[1][1:-1]
            elif pos[0] == 'adverbial':
                if pos[0] == 'adverbial':
                    pos_dict['type'] = pos[0]
                    try:
                        if pos[1] in ('comp', 'superl'):
                            pos_dict['comparison'] = pos[1]
                            word_dict['pos'] = pos_dict
                            inflections[headword] = word_dict
                        else:
                            pass
                    except:
                        pass
                else:
                    pass
            elif pos[0] in ('nom', 'abl', 'gen', 'dat', 'nom/acc', 'nom/voc'):
                pass
            elif pos[0] == 'sg':
                pass #??? ex: ut, uter, altus, alter
            elif pos[0] == 'comp':
                pass # ex: diu, se
            elif pos[0] in ('subj', 'ind'):
                pass # ex: fio, impleo, deleo, compleo
            elif pos[0] == 'nu_movable':
                pass #only 1 ex: sum
            else:
                pass

try:
    with open('cltk_analyses.txt', 'w') as new_file:
        #write_morph.write(str(inflections))
        pprint(inflections, stream=new_file)
except IOError:
    pass

from collections import deque
import numpy as np
import random
import abc

class QLearningAgent:
    def __init__(self, state_size, action_size):
        self.state_size = state_size
        self.action_size = action_size

        # hyperparameters
        self.gamma = 0.95  # discount rate on future rewards
        self.epsilon = 1.0  # exploration rate
        self.epsilon_decay = 0.995  # the decay of epsilon after each training batch
        self.epsilon_min = 0.1  # the minimum exploration rate permissible
        self.batch_size = 32  # maximum size of the batches sampled from memory

        # agent state
        self.model = self.build_model()
        self.memory = deque(maxlen=2000)

    @abc.abstractmethod
    def build_model(self):
        return None

    def select_action(self, state, do_train=True):
        if do_train and np.random.rand() <= self.epsilon:
            return random.randrange(self.action_size)
        elif do_train and np.random.rand() > self.epsilon:
            return np.argmax(self.model.predict(state)[0])
        else:
            print('Calling remote model...')

            ## TODO Change to call remote model
            return np.argmax(self.model.predict(state)[0])


    def record(self, state, action, reward, next_state, done):
        self.memory.append((state, action, reward, next_state, done))

    def replay(self):
        if len(self.memory) < self.batch_size:
            return 0

        minibatch = random.sample(self.memory, self.batch_size)
        for state, action, reward, next_state, done in minibatch:
            target = reward
            if not done:
                target = (reward + self.gamma *
                          np.amax(self.model.predict(next_state)[0]))
            target_f = self.model.predict(state)
            target_f[0][action] = target
            self.model.fit(state, target_f, epochs=1, verbose=0)

        if self.epsilon > self.epsilon_min:
            self.epsilon *= self.epsilon_decay

import chainer
import numpy
import pytest

import chainerx
import chainerx.testing

from chainerx_tests import array_utils
from chainerx_tests import dtype_utils
from chainerx_tests import math_utils
from chainerx_tests import op_utils


_in_out_dtypes_arithmetic_invalid = [
    (('bool_', 'bool_'), 'bool_'),
    (('bool_', 'int8'), 'int8'),
    (('bool_', 'int16'), 'int16'),
    (('bool_', 'int32'), 'int32'),
    (('bool_', 'int64'), 'int64'),
    (('bool_', 'uint8'), 'uint8'),
    (('bool_', 'float16'), 'float16'),
    (('bool_', 'float32'), 'float32'),
    (('bool_', 'float64'), 'float64'),
    (('int8', 'bool_'), 'int8'),
    (('int16', 'bool_'), 'int16'),
    (('int32', 'bool_'), 'int32'),
    (('int64', 'bool_'), 'int64'),
    (('uint8', 'bool_'), 'uint8'),
    (('float16', 'bool_'), 'float16'),
    (('float32', 'bool_'), 'float32'),
    (('float64', 'bool_'), 'float64'),
]


_in_out_dtypes_arithmetic = [
    dtypes for dtypes in dtype_utils.result_dtypes_two_arrays
    if dtypes not in _in_out_dtypes_arithmetic_invalid
]


_in_out_dtypes_inplace_arithmetic_invalid = [
    ((t1, t2), t3) for (t1, t2), t3 in _in_out_dtypes_arithmetic
    if (numpy.dtype(t1).kind != 'f' and numpy.dtype(t2).kind == 'f')
] + _in_out_dtypes_arithmetic_invalid


_in_out_dtypes_inplace_arithmetic = [
    dtypes for dtypes in dtype_utils.result_dtypes_two_arrays
    if dtypes not in _in_out_dtypes_inplace_arithmetic_invalid
]


_in_out_dtypes_array_int_scalar = [
    # Int scalar.
    (('int8',), int, 'int8'),
    (('int16',), int, 'int16'),
    (('int32',), int, 'int32'),
    (('int64',), int, 'int64'),
    (('uint8',), int, 'uint8'),
    (('float16',), int, 'float16'),
    (('float32',), int, 'float32'),
    (('float64',), int, 'float64'),
    (('int16',), numpy.int16, 'int16'),
    (('uint8',), numpy.int8, 'uint8'),
    (('float64',), numpy.int8, 'float64'),
    (('float16',), numpy.int64, 'float16'),
]


_in_out_dtypes_int_array_float_scalar = [
    # Int arrays and float scalars.
    (('int8',), float, 'float32'),
    (('int16',), float, 'float32'),
    (('int32',), float, 'float32'),
    (('int64',), float, 'float32'),
    (('uint8',), float, 'float32'),
    (('int8',), numpy.float32, 'float32'),
    (('int64',), numpy.float16, 'float32'),
    (('uint8',), numpy.float64, 'float32'),
]


_in_out_dtypes_float_array_float_scalar = [
    # Float arrays and flaot scalars.
    (('float16',), float, 'float16'),
    (('float32',), float, 'float32'),
    (('float64',), float, 'float64'),
    (('float64',), float, 'float64'),
    (('float16',), numpy.float64, 'float16'),
    (('float64',), numpy.float16, 'float64'),
]


_in_out_dtypes_arithmetic_scalar = (
    _in_out_dtypes_array_int_scalar
    + _in_out_dtypes_int_array_float_scalar
    + _in_out_dtypes_float_array_float_scalar)


_in_out_dtypes_inplace_arithmetic_scalar = (
    _in_out_dtypes_array_int_scalar
    + _in_out_dtypes_float_array_float_scalar)


_in_out_dtypes_float_arithmetic_scalar = (
    _in_out_dtypes_int_array_float_scalar
    + _in_out_dtypes_float_array_float_scalar)


_in_out_dtypes_inplace_float_arithmetic_scalar = (
    _in_out_dtypes_float_array_float_scalar)


@op_utils.op_test(['native:0', 'cuda:0'])
@chainer.testing.parameterize(*(
    # Special shapes
    chainer.testing.product({
        'shape': [(), (0,), (1,), (2, 0, 3), (1, 1, 1), (2, 3)],
        'in_dtypes,out_dtype': (
            dtype_utils.make_same_in_out_dtypes(
                1, chainerx.testing.numeric_dtypes)),
        'input': ['random'],
        'is_module': [False],
    })
    # is_module
    + chainer.testing.product({
        'shape': [(2, 3)],
        'in_dtypes,out_dtype': (
            dtype_utils.make_same_in_out_dtypes(
                1, chainerx.testing.numeric_dtypes)),
        'input': ['random'],
        'is_module': [True, False],
    })
    # Special values
    + chainer.testing.product({
        'shape': [(2, 3)],
        'in_dtypes,out_dtype': (
            dtype_utils.make_same_in_out_dtypes(
                1, chainerx.testing.float_dtypes)),
        'input': [float('inf'), -float('inf'), float('nan')],
        'is_module': [False],
        'skip_backward_test': [True],
        'skip_double_backward_test': [True],
    })
))
class TestNegative(math_utils.UnaryMathTestBase, op_utils.NumpyOpTest):

    def func(self, xp, a):
        if self.is_module:
            return xp.negative(a)
        else:
            return -a


@chainerx.testing.numpy_chainerx_array_equal(
    accept_error=(chainerx.DtypeError, TypeError))
@pytest.mark.parametrize_device(['native:0', 'cuda:0'])
def test_negative_invalid_bool(xp, device, is_module):
    x = xp.array([True, False], dtype='bool_')
    if is_module:
        xp.negative(x)
    else:
        -x


@op_utils.op_test(['native:0', 'cuda:0'])
@chainer.testing.parameterize(*(
    # Special shapes
    chainer.testing.product({
        'in_shapes': math_utils.shapes_combination_binary,
        'in_dtypes,out_dtype': (
            dtype_utils.make_same_in_out_dtypes(
                2, chainerx.testing.numeric_dtypes)),
        'input_lhs': ['random'],
        'input_rhs': ['random'],
        'is_module': [False],
    })
    # Dtype combinations
    + chainer.testing.product({
        'in_shapes': [((2, 3), (2, 3))],
        'in_dtypes,out_dtype': _in_out_dtypes_arithmetic,
        'input_lhs': ['random'],
        'input_rhs': ['random'],
        'is_module': [False],
    })
    # is_module
    + chainer.testing.product({
        'in_shapes': [((2, 3), (2, 3))],
        'in_dtypes,out_dtype': (
            dtype_utils.make_same_in_out_dtypes(
                2, chainerx.testing.numeric_dtypes)),
        'input_lhs': ['random'],
        'input_rhs': ['random'],
        'is_module': [True, False],
    })
    # Special values
    + chainer.testing.product({
        'in_shapes': [((2, 3), (2, 3))],
        'in_dtypes,out_dtype': (
            dtype_utils.make_same_in_out_dtypes(
                2, chainerx.testing.float_dtypes)),
        'input_lhs': ['random', float('inf'), -float('inf'), float('nan')],
        'input_rhs': ['random', float('inf'), -float('inf'), float('nan')],
        'is_module': [False],
        'skip_backward_test': [True],
        'skip_double_backward_test': [True],
    })
))
class TestAdd(math_utils.BinaryMathTestBase, op_utils.NumpyOpTest):

    def func(self, xp, a, b):
        if self.is_module:
            return xp.add(a, b)
        else:
            return a + b


@pytest.mark.parametrize_device(['native:0', 'cuda:0'])
@pytest.mark.parametrize('dtypes', _in_out_dtypes_arithmetic_invalid)
def test_add_invalid_dtypes(device, dtypes, is_module):
    (in_dtype1, in_dtype2), _ = dtypes
    shape = (2, 3)
    a = chainerx.array(array_utils.uniform(shape, in_dtype1))
    b = chainerx.array(array_utils.uniform(shape, in_dtype2))
    with pytest.raises(chainerx.DtypeError):
        if is_module:
            a + b
        else:
            chainerx.add(a, b)


@op_utils.op_test(['native:0', 'cuda:0'])
@chainer.testing.parameterize(*(
    # Special shapes
    chainer.testing.product({
        'in_shapes': math_utils.shapes_combination_inplace_binary,
        'in_dtypes,out_dtype': (
            dtype_utils.make_same_in_out_dtypes(
                2, chainerx.testing.numeric_dtypes)),
        'input_lhs': ['random'],
        'input_rhs': ['random'],
    })
    # Dtype combinations
    + chainer.testing.product({
        'in_shapes': [((2, 3), (2, 3))],
        'in_dtypes,out_dtype': _in_out_dtypes_inplace_arithmetic,
        'input_lhs': ['random'],
        'input_rhs': ['random'],
    })
    # Special values
    + chainer.testing.product({
        'in_shapes': [((2, 3), (2, 3))],
        'in_dtypes,out_dtype': (
            dtype_utils.make_same_in_out_dtypes(
                2, chainerx.testing.float_dtypes)),
        'input_lhs': ['random', float('inf'), -float('inf'), float('nan')],
        'input_rhs': ['random', float('inf'), -float('inf'), float('nan')],
        'skip_backward_test': [True],
        'skip_double_backward_test': [True],
    })
))
class TestIAdd(math_utils.InplaceBinaryMathTestBase, op_utils.NumpyOpTest):

    def func(self, xp, a, b):
        a += b


@pytest.mark.parametrize_device(['native:0', 'cuda:0'])
@pytest.mark.parametrize('dtypes', _in_out_dtypes_inplace_arithmetic_invalid)
def test_iadd_invalid_dtypes(device, dtypes):
    (in_dtype1, in_dtype2), _ = dtypes
    shape = (2, 3)
    a = chainerx.array(array_utils.uniform(shape, in_dtype1))
    b = chainerx.array(array_utils.uniform(shape, in_dtype2))
