class HopfieldModel(LatentModel):

    def __init__(self, nvis, nhid):
        self.layers = {}
        self.layers['visible'] = layers.IsingLayer(nvis)
        self.layers['hidden'] = layers.GaussianLayer(nhid)

        self.params = {}
        self.params['weights'] = numpy.random.normal(loc=0.0, scale=1.0, size=(self.layers['visible'].len, self.layers['hidden'].len)).astype(dtype=numpy.float32)
        self.params['bias'] = numpy.ones_like(self.layers['visible'].loc)  


class HookeMachine(LatentModel):

    def __init__(self, nvis, nhid, vis_type='gauss', hid_type='expo'):   
        assert vis_type.lower() in ['gauss', 'ising']
        assert hid_type.lower() in ['expo', 'bern']

        self.layers = {}
        self.layers['visible'] = layers.get(vis_type)(nvis)
        self.layers['hidden'] = layers.get(hid_type)(nhid)

        self.params = {}
        self.params['weights'] = numpy.random.normal(loc=0.0, scale=1.0, size=(self.layers['visible'].len, self.layers['hidden'].len)).astype(dtype=numpy.float32)
        self.params['bias'] = numpy.ones_like(self.layers['hidden'].loc)  
        self.params['T'] = numpy.ones(1, dtype=numpy.float32)

        self.deriv = {}
        self.deriv['weights'] = numpy.zeros_like(self.params['weights'])
        self.deriv['bias'] = numpy.zeros_like(self.params['bias'])
        self.params['T'] = numpy.zeros_like(self.params['T'])

        self.set_vis(numpy.zeros_like(self.layers['visible'].loc))

    def set_vis(self, vis):
        self.vis = vis
        self.diff = (self.params['weights'].T - vis).T
        self.squared_dist = numpy.sum(self.diff ** 2, axis=0)
        self.layers['hidden'].update_params(self.params['bias'] + self.squared_dist / (2 * self.params['T']))
        self.energy = -numpy.sum(numpy.log(self.layers['hidden'].partition_function()))        

    def visible_conditional_params(self, hid):
        total = numpy.sum(hid)
        loc = numpy.dot(self.params['weights'], hid) / total
        scale = self.params['T'] / total * numpy.ones_like(self.layers['visible'].loc)
        return (loc, scale)

    def update_visible_params(self, hid):
        self.layers['visible'].update_params(*self.visible_conditional_params(hid))

    def derivatives(self, vis, key):
        self.update_hidden_params(vis)
        hidden_mean = self.layers['hidden'].mean()
        if key == 'bias':
            # del H(v, k) / del b
            return hidden_mean
        elif key == 'weights':
            # del H(v, k) / del W
            return (self.difference(vis) * hidden_mean.T) / self.params['T']
        elif key == 'T':
            # del H(v,k) / del T
            return numpy.dot(hidden_mean.T, self.squared_distance(vis))
        else:
            raise ValueError('unknown key: {}'.format(key))
    """

# ----- FUNCTIONS ----- #

@jit('float32[:](float32[:,:],float32[:,:],float32[:,:])',nopython=True)
def batch_dot(vis, W, hid):
    result = numpy.zeros(len(vis), dtype=numpy.float32)
    for i in range(len(vis)):
        result[i] = numpy.dot(vis[i], numpy.dot(W, hid[i]))
    return result

import random
from typing import List

from chatette.units import Example, UnitDefinition
from .example import IntentExample


class IntentDefinition(UnitDefinition):
    """
    This class represents the definition of an intent,
    containing all the rules it can generate from.
    """

    def __init__(self, name, rules=None, arg=None, casegen=False):
        super(IntentDefinition, self).__init__(name, rules=rules, arg=arg, casegen=casegen)

        if rules is None:
            rules = []

        self.type = "intent"
        self.nb_training_examples_asked = None  # All possibilities will be generated TODO
        self.nb_testing_examples_asked = None

    def set_nb_examples_asked(self, nb_training_examples_asked, nb_testing_examples_asked=None):
        self.nb_training_examples_asked = nb_training_examples_asked
        self.nb_testing_examples_asked = nb_testing_examples_asked

    def generate(self, max_nb_examples, training_examples=None) -> List[Example]:
        """
        Generates all the examples that were asked (i.e. as much examples
        as asked). The number of generated examples is tied to a maximum though TODO.
        When `training_examples` is `None`, this will generate the training examples
        (i.e. the number of training examples asked), otherwise, it will generate
        examples that are not in `training_examples` (if possible).
        """
        if training_examples is None and self.nb_training_examples_asked is None:
            return [
                IntentExample(self.name, ex.text.strip(), ex.entities)
                for (i, ex) in enumerate(self.generate_all())
                if i < max_nb_examples]

        nb_examples_asked = self.nb_training_examples_asked
        if training_examples is not None:
            if self.nb_testing_examples_asked is None:
                return []  # No examples must be generated
            nb_examples_asked = self.nb_testing_examples_asked

        if nb_examples_asked <= 0:
            return []

        nb_possible_ex = self.get_nb_possible_generated_examples()
        if nb_examples_asked > nb_possible_ex:
            if training_examples is None:
                return [
                    IntentExample(self.name, ex.text.strip(), ex.entities)
                    for (i, ex) in enumerate(self.generate_all())
                    if i < max_nb_examples
                ]
            else:
                all_examples = [
                    IntentExample(self.name, ex.text.strip(), ex.entities)
                    for (i, ex) in enumerate(self.generate_all())
                    if i < max_nb_examples
                ]
                return [
                    ex
                    for ex in all_examples if ex not in training_examples
                ]

        if nb_examples_asked > max_nb_examples:
            nb_examples_asked = max_nb_examples

        if nb_examples_asked < nb_possible_ex / 2:  # QUESTION: should this be /2?
            generated_examples = []
            for _ in range(nb_examples_asked):

                while True:
                    current_example = self.generate_random()
                    current_example.text = current_example.text.strip()  # Strip for safety
                    if current_example not in generated_examples and \
                            (training_examples is None or current_example not in training_examples):
                        generated_examples.append(
                            IntentExample(self.name, current_example.text, current_example.entities))

                        break

            return generated_examples
        else:
            all_examples = [
                IntentExample(self.name, ex.text.strip(), ex.entities)
                for ex in self.generate_all()
            ]

            if training_examples is None:
                return random.sample(all_examples, nb_examples_asked)
            else:
                random.shuffle(all_examples)
                return [
                    ex for ex in all_examples
                    if ex not in training_examples
                ]

