import base64
import re
from datetime import datetime
from functools import reduce

from .table import Table

from six import BytesIO
import matplotlib

try:
    import mistune
except:
    raise ImportError('You need to install mistune to generate reports')


class EvaluatorSerializer:
    """Serializes elements in an evaluator to an appropriate format
    """
    def __init__(self, evaluator):
        self.evaluator = evaluator

    def __getattr__(self, key):
        attr = getattr(self.evaluator, key)

        if callable(attr):
            attr = attr()

        # serialize
        return attr


class ClassifierReport:

    def __init__(self, evaluator, template=None, style=None, env=None):
        # FIXME: support for many evaluators, maybe event support
        # dict like parameter
        self.evaluator = evaluator

        # here doing train returns the EvaluatorSerializer, not the
        # Classifierevaluator
        template = """

        # Report on the training set
        {{train.confusion_matrix()}}

        # Report on the tesing set
        {{test.confusion_matrix()}}
        """

    def render(self, embed_plots=True):
        pass

    def save(path):
        pass


def generate(evaluator, template, path=None, style=None):
    # extra tags that can also be used in the report but are not evaluator
    # attributes

    date_utc = '{} UTC'.format(datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S'))

    _extra_tags = {
        'date_utc':  date_utc,
        'date': datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S'),
    }

    # check if template is a path to a file
    # if yes, load the file
    if template.endswith('.md'):
        with open(template, 'r') as f:
            template = f.read()

    # strip lines in template
    lines = [l.strip() for l in template.splitlines()]
    template = reduce(lambda x, y: x+'\n'+y, lines)
    # get list of tags from template
    tags = parse_tags(template)

    # remove tags that are _extra_tags since they are not attributes
    # and the next function will fail
    tags = filter(lambda t: t not in _extra_tags.keys(), tags)

    # get attributes from evaluator using the tags
    attrs = getattr_from_list(evaluator, tags)

    # convert axes objects to HTML with base64,
    # Table to html
    for k, v in attrs.items():
        if isinstance(v, matplotlib.axes.Axes):
            attrs[k] = figure2html(v.get_figure())
        if isinstance(v, Table):
            attrs[k] = v.html

    # add key-value pairs to the attrs dict from the extra_tags
    attrs.update(_extra_tags)

    # replace tags with values
    report = template.format(**attrs)

    # compile to html and add style
    report = to_html(report, style)

    if path is not None:
        report_file = open(path, 'w')
        report_file.write(report)
        report_file.close()
    else:
        return report


def to_html(template, style):
    # Read md template and compile to html
    markdown = mistune.Markdown()
    html = markdown(template)

    # Add css
    if style is not None:
        f = open(style, 'r')
        css = f.read()
        html = '<style>'+css+'</style>'+html
    return html


def figure2html(fig):
    return base64_2_html(figure2base64(fig))


def base64_2_html(img):
    try:
        html = '<img src="data:image/png;base64,'+img+'"></img>'  # py2
    except:
        img = img.decode("utf-8")
        html = '<img src="data:image/png;base64,'+img+'"></img>'  # py3
    return html


def figure2base64(fig):
    io = BytesIO()
    fig.savefig(io, format='png')
    try:
        fig_base64 = base64.encodebytes(io.getvalue())  # py3
    except:
        fig_base64 = base64.encodestring(io.getvalue())  # py2
    return fig_base64


def prettify_list(l):
    l = [str(idx+1)+'. '+str(el) for idx, el in enumerate(l)]
    return reduce(lambda x, y: x+'<br>'+y, l)


def prettify_dict(d):
    return prettify_list([key+': '+str(d[key]) for key in d.keys()])


def parse_tags(s):
    """
        Return a list of tags (e.g. {tag_a}, {tag_b}) found in string s
    """
    return re.findall('{(\w+)\}*', s)


def getattr_from_list(obj, attr_names):
    def _get(obj, attr):
        attr = getattr(obj, attr)

        if callable(attr):
            attr = attr()

        return attr

    return {attr: _get(obj, attr) for attr in attr_names}

from __future__ import print_function
from __future__ import unicode_literals
from __future__ import division
from __future__ import absolute_import
from builtins import *  # NOQA
from future import standard_library
standard_library.install_aliases()  # NOQA

import collections

import six.moves.cPickle as pickle

from chainerrl.misc.collections import RandomAccessQueue
from chainerrl.replay_buffer import AbstractEpisodicReplayBuffer
from chainerrl.replay_buffer import random_subseq


class EpisodicReplayBuffer(AbstractEpisodicReplayBuffer):

    def __init__(self, capacity=None):
        self.current_episode = collections.defaultdict(list)
        self.episodic_memory = RandomAccessQueue()
        self.memory = RandomAccessQueue()
        self.capacity = capacity

    def append(self, state, action, reward, next_state=None, next_action=None,
               is_state_terminal=False, env_id=0, **kwargs):
        current_episode = self.current_episode[env_id]
        experience = dict(state=state, action=action, reward=reward,
                          next_state=next_state, next_action=next_action,
                          is_state_terminal=is_state_terminal,
                          **kwargs)
        current_episode.append(experience)
        if is_state_terminal:
            self.stop_current_episode(env_id=env_id)

    def sample(self, n):
        assert len(self.memory) >= n
        return self.memory.sample(n)

    def sample_episodes(self, n_episodes, max_len=None):
        assert len(self.episodic_memory) >= n_episodes
        episodes = self.episodic_memory.sample(n_episodes)
        if max_len is not None:
            return [random_subseq(ep, max_len) for ep in episodes]
        else:
            return episodes

    def __len__(self):
        return len(self.memory)

    @property
    def n_episodes(self):
        return len(self.episodic_memory)

    def save(self, filename):
        with open(filename, 'wb') as f:
            pickle.dump((self.memory, self.episodic_memory), f)

    def load(self, filename):
        with open(filename, 'rb') as f:
            memory = pickle.load(f)
        if isinstance(memory, tuple):
            self.memory, self.episodic_memory = memory
        else:
            # Load v0.2
            # FIXME: The code works with EpisodicReplayBuffer
            # but not with PrioritizedEpisodicReplayBuffer
            self.memory = RandomAccessQueue(memory)
            self.episodic_memory = RandomAccessQueue()

            # Recover episodic_memory with best effort.
            episode = []
            for item in self.memory:
                episode.append(item)
                if item['is_state_terminal']:
                    self.episodic_memory.append(episode)
                    episode = []

    def stop_current_episode(self, env_id=0):
        current_episode = self.current_episode[env_id]
        if current_episode:
            self.episodic_memory.append(current_episode)
            for transition in current_episode:
                self.memory.append([transition])
            self.current_episode[env_id] = []
            while self.capacity is not None and \
                    len(self.memory) > self.capacity:
                discarded_episode = self.episodic_memory.popleft()
                for _ in range(len(discarded_episode)):
                    self.memory.popleft()
        assert not self.current_episode[env_id]

