    # FIXME: Use linebased diff of some types of outputs:
    # if a.output_type in ("execute_result", "display_data"):
    #    a.data.key if key.startswith('text/') or key in _non_text_split_mimes = {
    #        'application/javascript','image/svg+xml'}
    #    a.text
    return diff(a, b)

