import tensorflow.compat.v1 as tf

# todo tf2 need a tf2 version of this function
def optimize(
        loss,
        training_parameters,
        learning_rate,
        global_step,
        horovod=None
):
    if training_parameters is not None and training_parameters['decay'] is True:
        learning_rate = tf.train.exponential_decay(
            learning_rate, global_step,
            training_parameters['decay_steps'],
            training_parameters['decay_rate'],
            staircase=training_parameters['staircase'])

    update_ops = tf.get_collection(tf.GraphKeys.UPDATE_OPS)

    with tf.variable_scope('optimizer'):
        if training_parameters is not None:
            optimizer_args = dict(training_parameters['optimizer'])
            optimizer_type = optimizer_args.pop('type')
            optimizer_fun = get_optimizer_fun(optimizer_type)
            if optimizer_type == 'adagradda':
                optimizer = optimizer_fun(learning_rate, global_step,
                                          **optimizer_args)
            else:
                optimizer = optimizer_fun(learning_rate, **optimizer_args)

            if horovod:
                optimizer = horovod.DistributedOptimizer(optimizer)

            optimize = optimizer.minimize(loss,
                                          global_step=global_step)
            if 'gradient_clipping' in training_parameters and \
                    training_parameters['gradient_clipping'] is not None:
                grad_clip_norm = training_parameters['gradient_clipping']
                gradients, variables = zip(*optimizer.compute_gradients(loss))
                gradients, _ = tf.clip_by_global_norm(gradients, grad_clip_norm)
                apply_grads = optimizer.apply_gradients(
                    zip(gradients, variables))
                increment_global_step = tf.assign(global_step,
                                                  global_step + 1)
                optimize = tf.group(apply_grads,
                                    increment_global_step)
        else:
            optimizer = tf.train.AdamOptimizer(learning_rate)

            if horovod:
                optimizer = horovod.DistributedOptimizer(optimizer)

            optimize = optimizer.minimize(loss,
                                          global_step=global_step)

    optimize = tf.group([optimize, update_ops])

    return optimize, learning_rate


def get_optimizer_fun(optimizer_type):
    optimizer_type = optimizer_type.lower()
    if (
            optimizer_type == 'sgd' or
            optimizer_type == 'stochastic_gradient_descent' or
            optimizer_type == 'gd' or
            optimizer_type == 'gradient_descent'
    ):
        return tf.train.GradientDescentOptimizer
    elif optimizer_type == 'adam':
        return tf.train.AdamOptimizer
    elif optimizer_type == 'adadelta':
        return tf.train.AdadeltaOptimizer
    elif optimizer_type == 'adagrad':
        return tf.train.AdagradOptimizer
    elif optimizer_type == 'adagradda':
        return tf.train.AdagradDAOptimizer
    elif optimizer_type == 'momentum':
        return tf.train.MomentumOptimizer
    elif optimizer_type == 'ftrl':
        return tf.train.FtrlOptimizer
    elif optimizer_type == 'proximalgd':
        return tf.train.ProximalGradientDescentOptimizer
    elif optimizer_type == 'proximaladagrad':
        return tf.train.ProximalAdagradOptimizer
    elif optimizer_type == 'rmsprop':
        return tf.train.RMSPropOptimizer
    else:
        raise ValueError('Invalid optimizer_type: ' + optimizer_type)


def get_optimizer_fun_tf2(optimizer_type):
    optimizer_type = optimizer_type.lower()
    if (
            optimizer_type == 'sgd' or
            optimizer_type == 'stochastic_gradient_descent' or
            optimizer_type == 'gd' or
            optimizer_type == 'gradient_descent'
    ):
        return tf.keras.optimizers.SGD()
    elif optimizer_type == 'adam':
        return tf.keras.optimizers.Adam()
    elif optimizer_type == 'adadelta':
        return tf.keras.optimizers.Adadelta()
    elif optimizer_type == 'adagrad':
        return tf.keras.optimizers.Adagrad()
    elif optimizer_type == 'adagradda':
        return None # tf.train.AdagradDAOptimizer  todo appears tf.keras.optimizers does not support
    elif optimizer_type == 'momentum':
        return None # tf.train.MomentumOptimizer  todo appears tf.keras.optimizers does not support
    elif optimizer_type == 'ftrl':
        return tf.keras.optimizers.Ftrl()
    elif optimizer_type == 'proximalgd':
        return None #tf.train.ProximalGradientDescentOptimizer todo appears tf.keras.optimizers does not support
    elif optimizer_type == 'proximaladagrad':
        return None #tf.train.ProximalAdagradOptimizer todo appears tf.keras.optimizers does not support
    elif optimizer_type == 'rmsprop':
        return tf.keras.optimizers.RMSprop()
    else:
        raise ValueError('Invalid optimizer_type: ' + optimizer_type)

# This file defines workaround implementation for
# NumPy-compatibility functions that fall back to NumPy/CuPy functions
# for native/cuda devices respecitvely.
# The workaround does not support backprop, and also requires external
# libraries mentioned above.
# Functions defined in this file should be considered to have high priority for
# genuine implementations.

import numpy

import chainerx


try:
    import cupy
except Exception:
    cupy = None


def _to_numpy(array):
    assert isinstance(array, chainerx.ndarray)
    return chainerx.to_numpy(array, copy=False)


def _from_numpy(array):
    assert isinstance(array, numpy.ndarray)
    return chainerx.array(array, copy=False)


def _to_cupy(array):
    assert cupy is not None
    # Convert to cupy.ndarray on the same device as source array
    return cupy.ndarray(
        array.shape,
        array.dtype,
        cupy.cuda.MemoryPointer(
            cupy.cuda.UnownedMemory(
                array.data_ptr + array.offset,
                array.data_size,
                array,
                array.device.index),
            0),
        strides=array.strides)


def _from_cupy(array):
    assert cupy is not None
    assert isinstance(array, cupy.ndarray)
    device = chainerx.get_device('cuda', array.device.id)
    return chainerx._core._fromrawpointer(
        array.data.mem.ptr,
        array.shape,
        array.dtype,
        array.strides,
        device,
        array.data.ptr - array.data.mem.ptr,
        array)


def _from_chainerx(array):
    # Converts chainerx.ndarray to numpy/cupy.ndarray.
    # Objects with other types are kept intact.
    if not isinstance(array, chainerx.ndarray):
        return array
    backend_name = array.device.backend.name
    if backend_name == 'native':
        return _to_numpy(array)
    if backend_name == 'cuda':
        if cupy is None:
            raise RuntimeError(
                'ChainerX fallback implementation for cuda backend requires '
                'cupy to be installed.')
        return _to_cupy(array)
    raise RuntimeError(
        'ChainerX fallback implementation only supports native or cuda '
        'backends.')


def _to_chainerx(array):
    # Converts numpy/cupy.ndarray to chainerx.ndarray.
    # Objects with other types are kept intact.
    if isinstance(array, numpy.ndarray):
        return _from_numpy(array)
    elif cupy is not None and isinstance(array, cupy.ndarray):
        return _from_cupy(array)
    return array


def populate():
    ndarray = chainerx.ndarray

    # __getitem__ with advanced indexing
    old_getitem = ndarray.__getitem__

    def __getitem__(arr, key):
        try:
            return old_getitem(arr, key)
        except (IndexError, chainerx.DimensionError):
            pass

        is_backprop_required = arr.is_backprop_required()

        arr = _from_chainerx(arr)
        key = _from_chainerx(key)

        if cupy is not None and isinstance(arr, cupy.ndarray):
            with arr.device:
                ret = arr[key]
        else:
            ret = arr[key]

        # Doing this check after the fallback __getitem__ because the error
        # which caused the fallback might not be due to advanced indexing.
        # In such case the fallback __getitem__ should also raise the error.

        if is_backprop_required:
            raise RuntimeError(
                'ChainerX getitem fallback for advanced indexing is not '
                'supported for arrays that are connected to a graph.')

        return _to_chainerx(ret)

    # __setitem__ with advanced indexing
    def __setitem__(self, key, value):
        if self.is_backprop_required():
            raise RuntimeError(
                'ChainerX setitem fallback for advanced indexing is not '
                'supported for arrays that are connected to a graph.')

        self = _from_chainerx(self)
        key = _from_chainerx(key)
        value = _from_chainerx(value)

        if cupy is not None and isinstance(self, cupy.ndarray):
            with self.device:
                self[key] = value
        else:
            self[key] = value

    ndarray.__setitem__ = __setitem__
    ndarray.__getitem__ = __getitem__

from __future__ import absolute_import
from __future__ import unicode_literals
from warnings import warn
import pathlib
from contextlib import contextmanager
import shutil

