import numpy as np

from spn.algorithms.StructureLearning import get_next_operation, learn_structure
from spn.algorithms.Validity import is_valid
from spn.algorithms.splitting.Clustering import get_split_rows_KMeans
from spn.algorithms.splitting.RDC import get_split_rows_RDC, get_split_cols_RDC_py, \
    get_split_rows_RDC_py
from spn.algorithms.splitting.Random import get_split_cols_binary_random_partition, \
    get_split_rows_binary_random_partition
from spn.algorithms.splitting.RCoT import getCIGroups

from spn.structure.Base import Sum, assign_ids

from spn.structure.leaves.histogram.Histograms import create_histogram_leaf
from spn.structure.leaves.parametric.Parametric import create_parametric_leaf
from spn.structure.leaves.piecewise.PiecewiseLinear import create_piecewise_leaf
from spn.structure.leaves.conditional.Conditional import create_conditional_leaf


def learn_classifier(data, ds_context, spn_learn_wrapper, label_idx):
    spn = Sum()
    for label, count in zip(*np.unique(data[:, label_idx], return_counts=True)):
        branch = spn_learn_wrapper(data[data[:, label_idx] == label, :], ds_context)
        spn.children.append(branch)
        spn.weights.append(count / data.shape[0])

    spn.scope.extend(branch.scope)
    assign_ids(spn)

    valid, err = is_valid(spn)
    assert valid, "invalid spn: " + err

    return spn


def learn_mspn_with_missing(data, ds_context, cols="rdc", rows="kmeans", min_instances_slice=200, threshold=0.3,
                            linear=False, ohe=False,
                            leaves=None, memory=None):
    if leaves is None:
        # leaves = create_histogram_leaf
        leaves = create_piecewise_leaf

    rand_gen = np.random.RandomState(17)

    def learn(data, ds_context, cols, rows, min_instances_slice, threshold, linear, ohe):
        split_cols = None
        if cols == "rdc":
            split_cols = get_split_cols_RDC_py(threshold, ohe=True, k=10, s=1 / 6,
                                               non_linearity=np.sin,
                                               rand_gen=rand_gen)
        if rows == "kmeans":
            split_rows = get_split_rows_RDC_py(n_clusters=2, ohe=True, k=10, s=1 / 6,
                                               non_linearity=np.sin,
                                               rand_gen=rand_gen)
        elif rows == "rdc":
            split_rows = get_split_rows_RDC(ohe=ohe)

        if leaves is None:
            leaves = create_histogram_leaf

        nextop = get_next_operation(min_instances_slice)

        return learn_structure(data, ds_context, split_rows, split_cols, leaves, nextop)

    if memory:
        learn = memory.cache(learn)

    return learn(data, ds_context, cols, rows, min_instances_slice, threshold, linear, ohe)


def learn_mspn(data, ds_context, cols="rdc", rows="kmeans", min_instances_slice=200, threshold=0.3, ohe=False,
               leaves=None, memory=None):
    if leaves is None:
        leaves = create_histogram_leaf

    def learn(data, ds_context, cols, rows, min_instances_slice, threshold, ohe):
        split_cols = None
        if cols == "rdc":
            split_cols = get_split_cols_RDC_py(threshold, ohe=ohe)
        if rows == "rdc":
            split_rows = get_split_rows_RDC_py(ohe=ohe)
        elif rows == "kmeans":
            split_rows = get_split_rows_KMeans()

        nextop = get_next_operation(min_instances_slice)

        return learn_structure(data, ds_context, split_rows, split_cols, leaves, nextop)

    if memory:
        learn = memory.cache(learn)

    return learn(data, ds_context, cols, rows, min_instances_slice, threshold, ohe)


def learn_parametric(data, ds_context, cols="rdc", rows="kmeans", min_instances_slice=200, threshold=0.3, ohe=False,
                     leaves=None, memory=None):
    if leaves is None:
        leaves = create_parametric_leaf

    def learn(data, ds_context, cols, rows, min_instances_slice, threshold, ohe):
        split_cols = None
        if cols == "rdc":
            split_cols = get_split_cols_RDC_py(threshold, ohe=ohe)
        if rows == "rdc":
            split_rows = get_split_rows_RDC_py(ohe=ohe)
        elif rows == "kmeans":
            split_rows = get_split_rows_KMeans()

        nextop = get_next_operation(min_instances_slice)

        return learn_structure(data, ds_context, split_rows, split_cols, leaves, nextop)

    if memory:
        learn = memory.cache(learn)

    return learn(data, ds_context, cols, rows, min_instances_slice, threshold, ohe)



def learn_conditional(data, ds_context, scope=None, cols="ci", rows="rand_hp", min_instances_slice=200, threshold=0.3, ohe=False,
                     leaves=None, memory=None):
    """
    :param data: np array
    :param ds_context: Context object
    :param scope: list of indices of output variables
    :param cols: column splitting method
    :param rows: row splitting method
    :param min_instances_slice: minimal instance slice
    :param threshold: threshold scalar
    :param ohe: ohe
    :param leaves: boolean
    :param memory: boolean
    :return: method to learn structure
    """
    if leaves is None:
        leaves = create_conditional_leaf

    def learn(data, ds_context, scope, cols, rows, min_instances_slice, threshold, ohe):
        split_cols = None
        if cols == "ci":
            split_cols = getCIGroups(data, scope, threshold)
        else:
            raise ValueError, 'invalid independence test'
        if rows == "rand_hp":
            split_rows = get_split_rows_binary_random_partition(ohe=ohe)
        else:
            #todo add other clustering?
            raise ValueError, 'invalid clustering method'

        nextop = get_next_operation(min_instances_slice)

        return learn_structure(data, ds_context, split_rows, split_cols, leaves, nextop, scope)

    if memory:
        learn = memory.cache(learn)

    return learn(data, ds_context, scope, cols, rows, min_instances_slice, threshold, ohe)

from deepbgc.output.writer import OutputWriter
from deepbgc import util
from deepbgc import __version__
import json

ANTISMASH_SUBREGION_LABEL_MAX_LENGTH = 20


class AntismashJSONWriter(OutputWriter):

    def __init__(self, out_path):
        super(AntismashJSONWriter, self).__init__(out_path)
        self.record_ids = []
        self.record_subregions = []
        self.record_protoclusters = []
        self.tool_meta = {}

    @classmethod
    def get_description(cls):
        return 'AntiSMASH JSON file for sideloading.'

    @classmethod
    def get_name(cls):
        return 'antismash-json'

    def write(self, record):
        cluster_features = util.get_cluster_features(record)
        classifier_names = util.get_record_classifier_names(record)
        subregions = []
        protoclusters = []
        for cluster in cluster_features:
            subregion = self._create_cluster_json(cluster, classifier_names=classifier_names)
            subregions.append(subregion)
            # TODO add protocluster?

        self.record_ids.append(record.id)
        self.record_subregions.append(subregions)
        self.record_protoclusters.append(protoclusters)
        # TODO add meta info from all detectors?
        if not self.tool_meta:
            self.tool_meta = util.get_record_detector_meta(record)

    def _get_cluster_classes_str(self, cluster, classifier_name):
        class_str_list = cluster.qualifiers.get(util.format_classification_column(classifier_name))
        return class_str_list[0] if class_str_list else 'no confident class'

    def _create_cluster_json(self, cluster, classifier_names):
        classes = {cls_name: self._get_cluster_classes_str(cluster, cls_name) for cls_name in classifier_names}
        tool_name = cluster.qualifiers.get('tool', ['unspecified'])[0]
        detector_name = cluster.qualifiers.get('detector', [tool_name])[0]
        score_column = util.format_bgc_score_column(detector_name)
        score = cluster.qualifiers.get(score_column)
        details = {
            'detector': detector_name,
        }
        details.update(classes)
        if score:
            details['score'] = score[0]
        return {
            'start': int(cluster.location.start),
            'end': int(cluster.location.end),
            'label': 'Putative BGC',
            'details': details
        }

    def _create_record_json(self, name, subregions, protoclusters):
        return {
            "name": name,
            "subregions": subregions,
            "protoclusters": protoclusters
        }

    def close(self):
        zipped_records = zip(self.record_ids, self.record_subregions, self.record_protoclusters)
        data = {
            "tool": {
                "name": "DeepBGC",
                "version": __version__,
                "description": "Putative BGCs predicted using DeepBGC",
                "configuration": self.tool_meta
            },
            "records": [self._create_record_json(name, sr, pc) for name, sr, pc in zipped_records]
        }
        with open(self.out_path, 'w') as f:
            json.dump(data, f, indent=2)

