#!/usr/bin/env python2

import numpy as np
from sklearn.neighbors.kd_tree import KDTree  # TODO pyflann??


class QEC(object):

    def __init__(self, actions, buffer_size, k, projection):
        self.buffers = tuple([ActionBuffer(buffer_size) for _ in actions])
        self.k = k
        self._projection = projection

    def project(self, observation):
        return np.dot(self._projection, observation.flatten())

    def estimate(self, state, action, time_step):
        a_buffer = self.buffers[action]
        state_index = a_buffer.find_state(state)

        if state_index:
            a_buffer.time_steps[state_index] = time_step  # TODO not in paper
            return a_buffer.values[state_index]

        if len(a_buffer) <= self.k:  # TODO init-phase
            return float('inf')

        value = .0
        neighbors = a_buffer.find_neighbors(state, self.k)
        for neighbor in neighbors:
            value += a_buffer.values[neighbor]
            a_buffer.time_steps[neighbor] = time_step  # TODO not in paper
        return value / self.k

    # TODO batch update
    def update(self, state, action, new_value, new_time):
        a_buffer = self.buffers[action]
        state_index = a_buffer.find_state(state)

        if state_index:
            old_value = a_buffer.values[state_index]
            old_time = a_buffer.time_steps[state_index]
            a_buffer.replace(state, max(old_value, new_value),
                             max(old_time, new_time), state_index)
        else:
            a_buffer.add(state, new_value, new_time)


class ActionBuffer(object):

    def __init__(self, capacity):
        self._tree = None
        self.capacity = capacity
        self.states = []
        self.values = []
        self.time_steps = []

    # TODO simply np.allclose over all states?
    def find_state(self, state):
        if self._tree:
            neighbor = self._tree.query([state])[1][0][0]
            # TODO check np.allclose
            if np.allclose(self.states[neighbor], state):
                return neighbor
        return None

    def find_neighbors(self, state, k):
        if self._tree:
            return self._tree.query([state], k)[1][0]
        return []

    def add(self, state, value, time_step):
        if len(self) < self.capacity:
            self.states.append(state)
            self.values.append(value)
            self.time_steps.append(time_step)
        else:
            self.replace(state, value, time_step, np.argmin(self.time_steps))

        # TODO smarter tree-update
        # memory ~ n_samples / leaf_size, default_leaf_size=40
        self._tree = KDTree(self.states)

    # TODO VQ/mean?
    def replace(self, state, value, time_step, index):
        self.states[index] = state
        self.values[index] = value
        self.time_steps[index] = time_step

    def __len__(self):
        return len(self.states)

from nala.features import FeatureGenerator
import re


class TmVarDefault(FeatureGenerator):
    """
    Generates tmVar CRF features based on the value of the token itself.
    * w[0] = the value of the words itself

    Implements the abstract class FeatureGenerator.
    """

    def generate(self, dataset):
        """
        :type dataset: structures.data.Dataset
        """
        self.reg_spec_chars = re.compile('.*[-;:,.>+_].*')
        self.reg_chr_keys = re.compile('.*(q|p|q[0-9]+|p[0-9]+|qter|pter|XY|t).*')
        self.reg_char_simple_bracket = re.compile('.*[\(\)].*')
        self.reg_char_square_bracket = re.compile('.*[\[\]].*')
        self.reg_char_curly_bracket = re.compile('.*[\{\}].*')
        self.reg_char_slashes = re.compile('.*[\/\\\].*')
        self.reg_mutat_type = re.compile('.*(del|ins|dup|tri|qua|con|delins|indel).*')
        self.reg_frameshift_type = re.compile('.*(fs|fsX|fsx).*')
        self.reg_mutat_word = re.compile('^(deletion|delta|elta|insertion|repeat|inversion|deletions|insertions|repeats|inversions).*')
        self.reg_mutat_article = re.compile('^(single|a|one|two|three|four|five|six|seven|eight|nine|ten|[0-9]+|[0-9]+\.[0-9]+).*')
        self.reg_mutat_byte = re.compile('.*(kb|mb).*')
        self.reg_mutat_basepair = re.compile('.*(base|bases|pair|amino|acid|acids|codon|postion|postions|bp|nucleotide|nucleotides).*')
        self.reg_type1 = re.compile('^[cgrm]$')
        self.reg_type12 = re.compile('^(ivs|ex|orf)$')
        self.reg_dna_symbols = re.compile('^[ATCGUatcgu]$')
        self.reg_prot_symbols1 = re.compile('.*(glutamine|glutamic|leucine|valine|isoleucine|lysine|alanine|glycine|aspartate|methionine|threonine|histidine|aspartic|asparticacid|arginine|asparagine|tryptophan|proline|phenylalanine|cysteine|serine|glutamate|tyrosine|stop|frameshift).*')
        self.reg_prot_symbols2 = re.compile('^(cys|ile|ser|gln|met|asn|pro|lys|asp|thr|phe|ala|gly|his|leu|arg|trp|val|glu|tyr|fs|fsx)$')
        self.reg_prot_symbols3 = re.compile('^(ys|le|er|ln|et|sn|ro|ys|sp|hr|he|la|ly|is|eu|rg|rp|al|lu|yr)$')
        self.reg_prot_symbols4 = re.compile('^[CISQMNPKDTFAGHLRWVEYX]$')
        self.reg_rs_code1 = re.compile('^(rs|RS|Rs)[0-9].*')
        self.reg_rs_code2 = re.compile('^(rs|RS|Rs)$')

        for token in dataset.tokens():
            # nr of digits
            # TODO 0,1,2,3,4+ instead of len = nr
            token.features['num_nr[0]'] = self.n_nr_chars(token.word)

            # nr of upper case
            token.features['num_up[0]'] = self.n_upper_chars(token.word)

            # nr of lower case
            token.features['num_lo[0]'] = self.n_lower_chars(token.word)

            # nr of chars
            token.features['length[0]'] = len(token.word)

            # nr of letters
            token.features['num_alpha[0]'] = self.n_chars(token.word)

            # nr of specific chars: ";:,.->+_"
            token.features['num_spec_chars[0]'] = self.spec_chars(token.word)

            # chromosomal keytokens
            token.features['num_has_chr_key[0]'] = self.is_chr_key(token.word)

            # mutation type
            token.features['mutat_type[0]'] = self.mutation_type(token.word)

            # mutation word
            token.features['mutat_word[0]'] = self.mutation_word(token.word)

            # mutation article and basepair
            token.features['mutat_article_bp[0]'] = self.mutation_article_bp(token.word)

            # type 1
            token.features['type1[0]'] = self.type1(token.word)

            # type 2
            token.features['type2[0]'] = self.type2(token.word)

            # dna symbols
            token.features['dna_symbols[0]'] = self.dna_symbols(token.word)

            # protein symbols
            token.features['protein_symbols[0]'] = self.protein_symbols(token.word)

            # RScode
            token.features['rs_code[0]'] = self.rscode(token.word)


    # NOTE check if ok the implementation (edge cases e.g. numeric means 123.232? or 123 and 232?)
    def n_lower_chars(self, str):
        return sum(1 for c in str if c.islower())

    def n_upper_chars(self, str):
        return sum(1 for c in str if c.isupper())

    def n_nr_chars(self, str):
        return sum(1 for c in str if c.isnumeric())

    def n_chars(self, str):
        return sum(1 for c in str if c.isalpha())

    def spec_chars(self, str):
        if self.reg_spec_chars.match(str):
            return "SpecC1"
        elif self.reg_char_simple_bracket.match(str):
            return "SpecC2"
        elif self.reg_char_curly_bracket.match(str):
            return "SpecC3"
        elif self.reg_char_square_bracket.match(str):
            return "SpecC4"
        elif self.reg_char_slashes.match(str):
            return "SpecC5"
        else:
            return None

    def is_chr_key(self, str):
        return "ChroKey" if self.reg_chr_keys.match(str) else None

    def mutation_type(self, str):
        if self.reg_frameshift_type.match(str):  # NOTE check if this is as in code (2x if but not if else)
            return "FrameShiftType"
        elif self.reg_mutat_type.match(str):
            return "MutatType"
        else:
            return None

    def mutation_word(self, str):
        return "MutatWord" if self.reg_mutat_word.match(str) else None

    def mutation_article_bp(self, str):
        mutat_article = ""  # NOTE is this programming ok?

        if self.reg_mutat_article.match(str):
            mutat_article = "Base"
        if self.reg_mutat_byte.match(str):
            mutat_article = "Byte"
        elif self.reg_mutat_basepair.match(str):
            mutat_article = "bp"
        else:
            mutat_article = None

        return mutat_article

    def type1(self, str):
        if self.reg_type1.match(str):
            return "Type1"
        elif self.reg_type12.match(str):
            return "Type1_2"
        else:
            return None

    def type2(self, str):
        return "Type2" if str == "p" else None

    def dna_symbols(self, str):
        return "DNASym" if self.reg_dna_symbols.match(str) else None

    def protein_symbols(self, str):
        uc_tmp = str  # upper case
        lc_tmp = str.lower()  # lower case

        if self.reg_prot_symbols1.match(lc_tmp):
            return "ProteinSymFull"
        elif self.reg_prot_symbols2.match(lc_tmp):
            return "ProteinSymTri"
        # TODO last token include: "&& $last_token[...]"
        elif self.reg_prot_symbols3.match(lc_tmp):
            return "ProteinSymTriSub"
        elif self.reg_prot_symbols4.match(uc_tmp):
            return "ProteinSymChar"
        else:
            return None

    def rscode(self, str):
        if self.reg_rs_code1.match(str):
            return "RSCode"
        elif self.reg_rs_code2.match(str):
            return "RSCode"
        else:
            return None

containing_method:
def __call__(self, fields, initial_annotations=None):
    start = time.perf_counter()
    if not initial_annotations:
        initial_annotations = []
    LOG.debug('initial annotations = %d', len(initial_annotations))

    if self.debug_visualizer:
        for stride, pif_i in zip(self.field_config.cif_strides, self.field_config.cif_indices):
            self.debug_visualizer.pif_raw(fields[pif_i], stride)
        for stride, paf_i in zip(self.field_config.caf_strides, self.field_config.caf_indices):
            self.debug_visualizer.paf_raw(fields[paf_i], stride)

    pifhr = PifHr(self.field_config).fill(fields)
    seeds = PifSeeds(pifhr.accumulated, self.field_config).fill(fields)
    # TODO make paf_scored not part of self?
    self.paf_scored = PafScored(pifhr.accumulated, self.field_config, self.skeleton).fill(fields)
    # pif init
    if self.debug_visualizer:
        self.debug_visualizer.pifhr(pifhr.accumulated)

    occupied = Occupancy(pifhr.accumulated.shape, 2, min_scale=4)
    annotations = []

    def mark_occupied(ann):
        for joint_i, xyv in enumerate(ann.data):
            if xyv[2] == 0.0:
                continue

            width = ann.joint_scales[joint_i]
            occupied.set(joint_i, xyv[0], xyv[1], width)

    for ann in initial_annotations:
        self._grow(ann)
        annotations.append(ann)
        mark_occupied(ann)

    for v, f, x, y, s in seeds.get():
        if occupied.get(f, x, y):
            continue

        ann = Annotation(self.keypoints, self.out_skeleton).add(f, (x, y, v))
        ann.joint_scales[f] = s
        self._grow(ann)
        annotations.append(ann)
        mark_occupied(ann)

    if self.debug_visualizer:
        self.debug_visualizer.occupied(occupied)

    LOG.debug('annotations %d, %.3fs', len(annotations), time.perf_counter() - start)

    if self.force_complete:
        annotations = self.complete_annotations(pifhr, fields, annotations)

    return annotations

