def _augment_images(self, images, random_state, parents, hooks):
    result = images
    nb_images = len(images)
    seeds = random_state.randint(0, 10**6, (nb_images,))

    if hooks is None or hooks.is_propagating(images, augmenter=self, parents=parents, default=True):
        if self.first is None:
            images_first = images
        else:
            images_first = self.first.augment_images(
                images=meta.copy_arrays(images),
                parents=parents + [self],
                hooks=hooks
            )

        if self.second is None:
            images_second = images
        else:
            images_second = self.second.augment_images(
                images=meta.copy_arrays(images),
                parents=parents + [self],
                hooks=hooks
            )
    else:
        images_first = images
        images_second = images

    # TODO simplify this loop and the ones for heatmaps, keypoints; similar to Alpha
    for i in sm.xrange(nb_images):
        image = images[i]
        h, w, nb_channels = image.shape[0:3]
        image_first = images_first[i]
        image_second = images_second[i]
        per_channel = self.per_channel.draw_sample(random_state=ia.new_random_state(seeds[i]))
        if per_channel > 0.5:
            alphas = []
            for c in sm.xrange(nb_channels):
                samples_c = self.factor.draw_samples((h, w), random_state=ia.new_random_state(seeds[i]+1+c))
                ia.do_assert(0 <= samples_c.item(0) <= 1.0) # validate only first value
                alphas.append(samples_c)
            alphas = np.float64(alphas).transpose((1, 2, 0))
        else:
            alphas = self.factor.draw_samples((h, w), random_state=ia.new_random_state(seeds[i]))
            ia.do_assert(0.0 <= alphas.item(0) <= 1.0)
        result[i] = blend_alpha(image_first, image_second, alphas, eps=self.epsilon)
    return result

def get_stencil_accesses(body, par_index_var):
    # TODO support recursive parfor, multi-D, mutiple body blocks
    const_table = {}
    stencil_accesses = {}

    for block in body.values():
        for stmt in block.body:
            if isinstance(stmt, ir.Assign) and isinstance(stmt.value, ir.Const):
                lhs = stmt.target.name
                const_table[lhs] = stmt.value.value
            if isinstance(stmt, ir.Assign) and isinstance(stmt.value, ir.Expr):
                lhs = stmt.target.name
                rhs = stmt.value
                if (rhs.op == 'binop' and rhs.fn == '+' and
                        rhs.lhs.name == par_index_var and
                        rhs.rhs.name in const_table):
                    stencil_accesses[lhs] = const_table[rhs.rhs.name]

    return stencil_accesses

def GetProblemType(key,tileAware,disableHpa):
    _ , transposeA, transposeB, dType = key

    initialParams = {}

    if transposeA == "N":
        initialParams["TransposeA"] = False
    else:
        initialParams["TransposeA"] = True

    if transposeB == "N":
        initialParams["TransposeB"] = False
    else:
        initialParams["TransposeB"] = True
    initialParams["DataType"] = dType[0]
    initialParams["DestDataType"] = dType[1]
    initialParams["ComputeDataType"] = dType[2]

    if (dType[0] == "h" or dType[0] == "b") and dType[2] == "s":
        if disableHpa:
            # TODO this combo doens't work
            print("input half and compute single requires hpa")
            pass
        initialParams["HighPrecisionAccumulate"] = True


    problemType = generateProblemType(initialParams,tileAware)

    return problemType

