def build_array_placeholders(batch_size, neighbourhood_sizes, features_length,
                             feature_types: typ.Union[typ.List[typ.MutableMapping[str, tf.DType]], tf.DType]):
    array_neighbourhood_sizes = list(reversed(neighbourhood_sizes))
    neighbourhood_placeholders = []
    for i in range(len(array_neighbourhood_sizes) + 1):
        shape = [batch_size] + list(array_neighbourhood_sizes[i:]) + [features_length]

        try:
            phs = tf.placeholder(feature_types, shape=shape)
        except:
            phs = {name: tf.placeholder(type, shape=shape) for name, type in feature_types[i].items()}

        neighbourhood_placeholders.append(phs)
    return neighbourhood_placeholders

def _transform_ls(self, X):
    n_test, _ = X.shape
    n_train = self.X_train_.shape[0]
    k = self.n_samples
    kth = self.n_neighbors
    if self.sampling_algorithm in ['hnsw', 'lsh']:
        # TODO use X_nrom_squared
        if self.sampling_algorithm == 'hnsw':
            ind, D_test = self._hnsw_trafo(X, k)
        elif self.sampling_algorithm == 'lsh':
            ind, D_test = self._lsh_trafo(X, k)
        self.ind_test_ = ind
        r_test = D_test[:, :self.n_neighbors] # already sorted
    else:
        if self.verbose > 2:
            print(f'HR.transform(full)')
        D_test = euclidean_distances(
            X, self.X_train_, Y_norm_squared=self.X_train_norm_squared_,
            squared=True)
        ind = np.tile(np.arange(n_train), n_test).reshape((n_test, n_train))
        self.ind_test_ = self.ind_train_
        r_test = np.partition(D_test, kth=kth)[:, :kth]
    # Calculate LS or NICDM
    D_sec = np.empty_like(D_test)
    sample_ind = self.ind_train_
    if self.hr_algorithm.upper() == 'LS':
        r_train = np.sort(self.r_train_)[:, kth-1]
        r_test = np.sort(r_test)[:, kth-1]
        for i in range(n_test):
            if self.fixed_vantage_pts_:
                D_sec[i, :] = 1 - np.exp(-1 * D_test[i]**2 \
                                         / (r_test[i] * r_train[:]))
            else:
                D_sec[i, :] = \
                    1 - np.exp(-1 * D_test[i]**2 \
                               / (r_test[i] * r_train[sample_ind[i]]))
    elif self.hr_algorithm.upper() == 'NICDM':
        r_train = self.r_train_.mean(axis=1)
        r_test = r_test.mean(axis=1)
        for i in range(n_test):
            if self.fixed_vantage_pts_:
                D_sec[i, :] = D_test[i] / np.sqrt((r_test[i] * r_train[:]))
            else:
                D_sec[i, :] = D_test[i] / np.sqrt((r_test[i] * r_train[sample_ind[i]]))
    else:
        raise ValueError(f"Invalid 'hr_algorithm' {self.hr_algorithm} "
                         f"in '_transform_ls()'.")
    self.sec_dist_ = D_sec
    return None

