from flask import Blueprint, render_template, request, jsonify
from flask_login import login_required, current_user
from werkzeug.exceptions import NotFound
from acousticbrainz.data import dataset
from jsonschema import ValidationError, validate as validate_json

datasets_bp = Blueprint('datasets', __name__)


@datasets_bp.route('/<uuid:id>/')
def details(id):
    ds = dataset.get(id)
    if not ds:
        raise NotFound("Can't find this dataset.")
    return render_template('datasets/view.html', dataset=ds)


@datasets_bp.route('/create/', methods=('GET', 'POST'))
@login_required
def create():
    if request.method == 'POST':
        dataset_dict = request.get_json()
        if not dataset_dict:
            return jsonify(
                success=False,
                error="Data must be submitted in JSON format.",
            ), 400

        try:
            validate_json(dataset_dict, dataset.DATASET_JSON_SCHEMA)
        except ValidationError as e:
            return jsonify(
                success=False,
                error=str(e),
            ), 400

        dataset_id, error = dataset.create_from_dict(dataset_dict, current_user.id)
        if dataset_id is None:
            return jsonify(
                success=False,
                error=str(error),
            ), 400

        return jsonify(
            success=True,
            dataset_id=dataset_id,
        )
    return render_template('datasets/create.html')


@datasets_bp.route('/<uuid:id>/edit/', methods=('GET', 'POST'))
@login_required
def edit(id):
    ds = dataset.get(id)
    if not ds:
        raise NotFound("Can't find this dataset.")
    # TODO: Check if owner is editing.
    # TODO: Implement the rest of the editing stuff.
    raise NotImplementedError


@datasets_bp.route('/<uuid:id>/delete/', methods=('GET', 'POST'))
@login_required
def delete(id):
    ds = dataset.get(id)
    if not ds:
        raise NotFound("Can't find this dataset.")
    # TODO: Check if owner is deleting.
    # TODO: Show confirmation page and delete if POSTed.
    raise NotImplementedError

"""
Collect and send metrics about program usage
"""

from configparser import (
    ConfigParser, NoSectionError
)
import io
import pkg_resources
import requests

from loudml.misc import my_host_id


# Workaround for ConfigParser requiring sections
# https://mail.python.org/pipermail/python-dev/2002-November/029987.html
class MyConfigParser(ConfigParser):
    def read(self, filename):
        try:
            text = open(filename).read()
        except IOError:
            pass
        else:
            file = io.StringIO("[os-release]\n" + text)
            self.readfp(file, filename)

    def safe_get(self, section, val):
        # Issue #208: /etc/os-release not always present
        # On macOS it is: /System/Library/CoreServices/SystemVersion.plist
        # TODO: consider more granular OS release extraction
        try:
            return self.get(section, val)
        except NoSectionError:
            return "N/A"


def send_metrics(config, storage, user_agent="loudmld"):
    """
    Send usage information to telemetry server

     :param config:      telemetry configuration
     :type  config:      dict
     :param storage:     storage backend
     :type  storage:     loudml.Storage
     :param user_agent:  HTTP request user agent
     :type  user_agent:  str
    """
    if not config['enable']:
        return

    os_release = MyConfigParser()
    os_release.read("/etc/os-release")

    url = 'http://telemetry.loudml.io/api'
    data = {
        'host_id': my_host_id(),
        'loudml': {
            'distribution': os_release.safe_get("os-release", "NAME"),
            'nr_models': len(storage.list_models()),
            'version': pkg_resources.get_distribution("loudml").version,
        },
    }
    headers = {
        'user-agent': user_agent,
    }

    try:
        requests.post(url, json=data, headers=headers)
    except Exception:
        # Ignore error as it may be expected in some environments (offline...)
        pass

