def evaluate(self, dataset, metrics, transformers=[], per_task_metrics=False,
  no_concordance_index=False, plot=False, is_training_set=False, tasks=None, 
  model_name=None):
  if not self.built:
    self.build()
  return self.evaluate_generator(

def test_mean1(self):
    # TODO: non-numeric columns should be ignored automatically
    def test_impl(n):
        df = pd.DataFrame({'A': np.arange(n)+1.0, 'B': np.arange(n)+1})
        return df.mean()

    hpat_func = hpat.jit(test_impl)
    n = 11
    pd.testing.assert_series_equal(hpat_func(n), test_impl(n))

def _get_series_array_type(dtype):
    """get underlying default array type of series based on its dtype
    """
    # list(list(str))
    if dtype == types.List(string_type):
        # default data layout is list but split view is used if possible
        return list_string_array_type
    # string array
    elif dtype == string_type:
        return string_array_type

    # categorical
    if isinstance(dtype, PDCategoricalDtype):
        return CategoricalArray(dtype)

    # use recarray data layout for series of tuples
    if isinstance(dtype, types.BaseTuple):
        if any(not isinstance(t, types.Number) for t in dtype.types):
            # TODO: support more types. what types can be in recarrays?
            raise ValueError("series tuple dtype {} includes non-numerics".format(dtype))
        np_dtype = np.dtype(
            ','.join(str(t) for t in dtype.types), align=True)
        dtype = from_dtype(np_dtype)

    # TODO: other types?
    # regular numpy array
    return types.Array(dtype, 1, 'C')

def clone(self):
  """Returns a deep copy of self"""
  return History(copy.deepcopy(self._states))

def match_template(resp, fields, params):

    # TODO: finalise this function so the template is actually used for natural
    #      language generation in the output
    matching_templates = []

    templates = [
        {
            'intent': 'feature_example',
            'template_text': 'Template 1: Example $NUMBER'},
        {
            'intent': 'feature_example',
            'template_text': 'Template 2: Example $FEATURE'}
        ]

    for t in templates:
        if t['intent'] == resp['intent']:
            matching_templates.append(t)

    # TODO: put in a better 'fitness' selection process here!!
    chosen_template = random.choice(matching_templates)
    # TODO: put in the option to do substitution here (most likely scenario,
    #      barring edge cases)
    return chosen_template['template_text']

def _validate_data_hooks(self, model):
    # Raise Misconfiguration exception since these hooks are not supported in DP mode
    # TODO: Remove this blocker once batch transfer to device is integrated in Lightning for DP mode.
    batch_transfer_hooks = ('on_before_batch_transfer', 'transfer_batch_to_device', 'on_after_batch_transfer')
    for hook in batch_transfer_hooks:

def on_validation_end(self, trainer, pl_module):
    # only run on main process
    if trainer.global_rank != 0:
        return

    # TODO: remove when dict results are deprecated
    self.__warn_deprecated_monitor_key()

    metrics = trainer.callback_metrics
    epoch = trainer.current_epoch

    # support structured results
    if metrics.get('checkpoint_on') is not None:
        self.monitor = 'checkpoint_on'

    # conditioned val metrics override conditioned train loop metrics
    if metrics.get('val_checkpoint_on') is not None:
        self.monitor = 'val_checkpoint_on'

    if self.save_top_k == 0:
        # no models are saved
        return
    if self.epoch_last_check is not None and (epoch - self.epoch_last_check) < self.period:
        # skipping in this term
        return

    self.epoch_last_check = epoch

    filepath = self.format_checkpoint_name(epoch, metrics)
    version_cnt = 0
    while gfile.exists(filepath):
        filepath = self.format_checkpoint_name(epoch, metrics, ver=version_cnt)
        # this epoch called before
        version_cnt += 1

    if self.save_top_k != -1:
        current = metrics.get(self.monitor)

        if not isinstance(current, torch.Tensor):
            rank_zero_warn(
                f'The metric you returned {current} must be a `torch.Tensor` instance, checkpoint not saved'
                f' HINT: what is the value of {self.monitor} in validation_epoch_end()?', RuntimeWarning
            )
            if current is not None:
                current = torch.tensor(current)

        if current is None:
            rank_zero_warn(
                f'Can save best model only with {self.monitor} available, skipping.', RuntimeWarning
            )
        elif self.check_monitor_top_k(current):
            self._do_check_save(filepath, current, epoch, trainer, pl_module)
        elif self.verbose > 0:
            log.info(f'\nEpoch {epoch:05d}: {self.monitor}  was not in top {self.save_top_k}')

    else:
        if self.verbose > 0:
            log.info(f'\nEpoch {epoch:05d}: saving model to {filepath}')

        assert trainer.global_rank == 0, 'tried to make a checkpoint from non global_rank=0'
        self._save_model(filepath, trainer, pl_module)

    if self.save_last:

