def freqstr(self):
    try:
        code = self.rule_code
    except NotImplementedError:
        return repr(self)

    if self.n != 1:
        fstr = '{n}{code}'.format(n=self.n, code=code)
    else:
        fstr = code

    try:
        if self._offset:
            fstr += self._offset_str()
    except AttributeError:
        # TODO: standardize `_offset` vs `offset` naming convention
        pass

    return fstr

